#[test]
fn the_leakage_inventory_is_frozen() {
    let built = build_inventory();
    let frozen: Vec<String> = INVENTORY.iter().map(|s| s.to_string()).collect();
    if built != frozen {
        let mut diff = Vec::new();
        for (i, (b, f)) in built.iter().zip(&frozen).enumerate() {
            if b != f {
                diff.push(format!("line {i}:\n  frozen: {f}\n  built:  {b}"));
            }
        }
        if built.len() != frozen.len() {
            diff.push(format!("frozen has {} lines, built has {}", frozen.len(), built.len()));
        }
        panic!(
            "the API lineage's leakage surface moved — regenerate with `--ignored \
             regenerate_leakage_inventory_pending` and REVIEW the diff:\n{}",
            diff.join("\n")
        );
    }
}

/// COMPLETENESS, as a hard gate: every witness-dependent wire that reaches
/// the public statement carries a declared label in its ancestry.
#[test]
fn no_unlabelled_witness_dependent_public_component() {
    let offenders: Vec<String> = build_inventory()
        .into_iter()
        .filter(|l| l.starts_with("unlabelled witness-dependent public components | "))
        .filter(|l| !l.ends_with("| none"))
        .collect();
    assert!(offenders.is_empty(), "{}", offenders.join("\n"));
}

/// M37 rung D's exit criterion, read off the inventory: NO SETTLE CIRCUIT
/// CONSUMES AN UNCHECKED SECRET. Two conditions on each `complete_*` /
/// `refund_*` circuit's witness lines:
///
/// 1. none is `checks: unchecked` — every `private_input` reaches some
///    `assert` / `constrain_*`; and
/// 2. a witness that reaches NO declared label — one the circuit keeps
///    rather than publishes, i.e. a SECRET — reaches an `assert`, not
///    merely a `constrain_bits` range check. Without (2) the gate would be
///    satisfiable by the bit decomposition every witnessed limb gets for
///    free, which constrains the value's WIDTH and nothing about the
///    statement. What (2) demands is the authorization: the secret opens
///    the stored owner commitment against the request id.
///
/// A witness that DOES reach a label is a published component
/// (`own_public_key`'s two limbs, disclosed as the mint recipient), and
/// `no_unlabelled_witness_dependent_public_component` is its gate.
///
/// The compat lineage cannot state this: `completeWithdraw` there consumes
/// its secret unconditionally and checks it only under the attested
/// outcome (Gap 2, §7.2's V5 reading — its one `assert` depends also on
/// `in:%serializedOutput.9`). Here the outcome picks the circuit, so the
/// consumption and the check cannot come apart.
#[test]
fn no_settle_consumes_an_unchecked_secret() {
    let blocks = per_circuit(&build_inventory());
    let settles: Vec<&(String, Vec<String>)> = blocks.iter().filter(|(n, _)| is_settle(n)).collect();
    assert_eq!(
        settles.len(),
        8,
        "the lineage has eight settles (four flows × complete/refund); found {:?}",
        settles.iter().map(|(n, _)| n).collect::<Vec<_>>()
    );
    let mut offenders: Vec<String> = Vec::new();
    for (name, lines) in &settles {
        for line in lines.iter().filter(|l| l.starts_with("witness w")) {
            let checks = line.split("| checks: ").nth(1).expect("a witness line has checks");
            if checks == "unchecked" {
                offenders.push(format!("{name}: reads a witness nothing checks — {line}"));
            } else if line.contains("| reaches labels: none |") && !checks.contains("assert ") {
                offenders.push(format!(
                    "{name}: an UNPUBLISHED witness is only range-checked, never asserted — {line}"
                ));
            }
        }
    }
    assert!(
        offenders.is_empty(),
        "a settle circuit reads a secret it does not check — the private transcript is \
         consumed for something nothing constrains:\n{}",
        offenders.join("\n")
    );
}

/// `complete_withdraw` reads NOTHING from the private transcript: the
/// completion is anyone's (the tokens have left the vault's EVM account and
/// there is nothing to mint), so there is no owner gate and no secret to
/// hoist. This is the one settle whose statement M37 rung D changed most
/// (k16 → k15, 35,553 → 25,655 rows — notes/evm-calls.org §11); if a
/// witness ever reappears here the completion has stopped being anyone's.
#[test]
fn complete_withdraw_consumes_no_witness() {
    let blocks = per_circuit(&build_inventory());
    let (_, lines) = blocks
        .iter()
        .find(|(n, _)| n == "complete_withdraw")
        .expect("the lineage has a `complete_withdraw`");
    let witnesses: Vec<&String> = lines.iter().filter(|l| l.starts_with("witness w")).collect();
    assert!(
        witnesses.is_empty(),
        "`complete_withdraw` reads the private transcript again:\n{}",
        witnesses.iter().map(|l| l.as_str()).collect::<Vec<_>>().join("\n")
    );
    let header = &lines[0];
    assert!(
        header.contains("| witnesses 0 (guarded 0) |"),
        "the header disagrees with the witness lines: {header}"
    );
}

#[test]
#[ignore]
fn regenerate_leakage_inventory_pending() {
    let body: String = build_inventory()
        .iter()
        .map(|l| format!("    {l:?},\n"))
        .collect();
    rewrite_generated_region(&test_source("leakage_inventory_pending.rs"), &body);
}
